def is_valid_ifsc(code: str) -> bool:
    # IFSC: 4 letters, a 0, then 6 alphanumerics (RBI format)
    import re
    return bool(re.fullmatch(r'[A-Z]{4}0[A-Z0-9]{6}', code))
